package com.yuegang.zhihui.training.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.training.infrastructure.*;import com.yuegang.zhihui.training.security.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;@Configuration(proxyBeanMethods=false)class TrainingConfiguration{@Bean TrainingProgressService trainingProgressService(DataSource d){return new TrainingProgressService(d);}@Bean TrainingQuizService trainingQuizService(DataSource d,ObjectMapper o){return new TrainingQuizService(d,o);}@Bean TrainingAssignmentService trainingAssignmentService(DataSource d,ObjectMapper o){return new TrainingAssignmentService(d,o);}@Bean ScopedAssignmentService scopedAssignmentService(TrainingAssignmentService a,OrganizationTargetClient t){return new ScopedAssignmentService(a,t);}@Bean OrganizationTargetClient organizationTargetClient(@Value("${ygh.training.user-base-url}")String b,@Value("${ygh.internal-request.hmac-base64}")String e,ObjectMapper j){byte[]k=Base64.getDecoder().decode(e);try{return new OrganizationTargetClient(b,k,j);}finally{Arrays.fill(k,(byte)0);}}@Bean LearningPathService learningPathService(DataSource d){return new LearningPathService(d);}@Bean TrainingContentService trainingContentService(DataSource d,ObjectMapper o,@Value("${ygh.training.storage-root}")String r){return new TrainingContentService(d,o,r);}@Bean TrainingUserResolver trainingUserResolver(@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new TrainingUserResolver(k);}finally{Arrays.fill(k,(byte)0);}}}
